export type PluginAuthField = {
  /** Environment variable name, header slot, or arg slot the value feeds. */
  key: string
  label: string
  placeholder: string
  /** Masks the input. Leave unset for identifiers the user needs to see. */
  secret?: boolean
}

export type PluginAuth =
  | { kind: "none" }
  | { kind: "oauth" }
  | { kind: "token"; fields: PluginAuthField[]; docsUrl: string; docsLabel: string }

export type PluginDef = {
  /** Also used as the MCP server name when installed. */
  id: string
  name: string
  blurb: string
  category: string
  /** simple-icons slug into brandPaths. */
  logo: keyof typeof brandPaths
  /** Logo fill on the dark chip; dark brand marks are lightened for contrast. */
  fill: string
  badge?: "community"
  soon?: boolean
  auth: PluginAuth
  build?: (values: Record<string, string>) => McpLocalConfig | McpRemoteConfig
}

const local = (command: string[], environment?: Record<string, string>): McpLocalConfig => ({
  type: "local",
  command,
  environment,
  enabled: true,
  timeout: 120_000,
})

const remote = (url: string, headers?: Record<string, string>): McpRemoteConfig => ({
  type: "remote",
  url,
  headers,
  // Hosted connectors without an explicit token rely on the server's OAuth
  // auto-detection; token-based ones authenticate via headers, so detection
  // must be disabled or the backend still attaches an OAuth provider.
  oauth: headers ? false : undefined,
  enabled: true,
  timeout: 120_000,
})

